// Кейс: .qa/tests/expert/EXP-008.md · план: .qa/e2e-app/specs/app.md (1.42)
// РУЧНОЕ ПРЕДУСЛОВИЕ: приложение залогинено под экспертом jleprog34, запуск с BANCI_ACCOUNT=jleprog34 (иначе — пропуск).
// Тест НИЧЕГО не сохраняет: «שמירת החוקים» не нажимается, перед выходом приложение перезапускается (введённые значения теряются).
import { by, assert } from '../../lib/appium.mjs';
import { requireExpert, openExpert, fieldBelow, blur, key, clearFocused, value } from '../../lib/expert.mjs';

export const name = '«חוקי זיהוי»: в цифровой клавиатуре числовых полей есть «.» и «,»; «0,3» → «0.3»; буквы → «צריך להיות מספר בין…»; без сохранения #58001d @iphone @app @prod-safe';

const FIELDS = ['מרחק משפת המים', 'ראש מתחת למים']; // «לפחות»: поле расстояния и поле сценария (ticket: «למשל מרחק משפת המים»)

export default async function (app) {
  requireExpert();
  await openExpert(app);

  for (const label of FIELDS) {
    const field = await fieldBelow(app, label);
    await field.click();

    // 1. Клавиатура: есть и «.», и «,»; кнопка «שמירת החוקים» не пропала (только проверяем наличие, не нажимаем).
    await app.waitFor(key('.'), { what: `клавиша «.» на клавиатуре поля «${label}»` });
    await app.waitFor(key(','), { what: `клавиша «,» на клавиатуре поля «${label}» (#58001d: только точка = баг)` });
    assert(await app.exists(by.exact('שמירת החוקים')), `«שמירת החוקים» видна при открытой клавиатуре (поле «${label}»)`);

    // 2. «,» вставляется в поле, а не игнорируется: «0,3».
    await clearFocused(app, field);
    await app.tap(key('0'));
    await app.tap(key(','));
    await app.tap(key('3'));
    const typed = await value(field);
    assert(typed === '0,3', `после «0», «,», «3» в поле «${label}» — «0,3» (сейчас «${typed}»)`);

    // 3. Выход из поля: запятая → точка, как и раньше (#1b17df).
    await blur(app, label);
    const after = await value(field);
    assert(after === '0.3', `после выхода из поля «${label}» «0,3» → «0.3» (сейчас «${after}»)`);
  }

  // 4. Нечисловой ввод в последнем поле: сообщение с диапазоном (прежняя проверка, #89216b AC4), ничего не сохраняется.
  const last = await fieldBelow(app, FIELDS[FIELDS.length - 1]);
  await last.click();
  await clearFocused(app, last);
  await last.type('abc');
  await blur(app, FIELDS[FIELDS.length - 1]);
  await app.waitFor(by.contains('צריך להיות מספר בין'), { what: 'сообщение «צריך להיות מספר בין …» под полем с «abc»' });
  assert(!(await app.exists(by.exact('החוקים נשמרו'))), 'сообщения «החוקים נשמרו» нет — ничего не сохранено');
  await app.screenshot('58001d-letters-error');
  await app.restart(); // введённые значения не сохранены и пропадают
}
